112	<script>
113	  import router from '@system.router';
114	
115	  export default {
116	    data: {
117	      monitoring: true,
118	      currentTime: '--:--',
119	      healthScore: 85,
120	      scoreDesc: '体态良好，继续保持',
121	      todayAbnormal: 0,
122	      monitorMinutes: 0,
123	      records: [],
124	      _timer: null,
125	      _startTime: 0,
126	      _window: [],
127	      _lastType: 'NORMAL',
128	      _anomalyStart: 0,
129	      _lastReminder: {},
130	    },
131	
132	    onInit() {
133	      this._startTime = Date.now();
134	      this._startMockSensor();
135	      this._startTimer();
136	    },
137	
138	    onDestroy() {
139	      if (this._timer) clearInterval(this._timer);
140	      if (this._mockTimer) clearInterval(this._mockTimer);
141	    },
142	
143	    _startTimer() {
144	      this._updateTime();
145	      this._timer = setInterval(() => {
146	        this._updateTime();
147	        this._updateStats();
148	      }, 1000);
149	    },
150	
151	    _updateTime() {
152	      var d = new Date();
153	      var h = d.getHours();
154	      var m = d.getMinutes();
155	      this.currentTime = (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m;
156	    },
157	
158	    _updateStats() {
159	      this.monitorMinutes = Math.floor((Date.now() - this._startTime) / 60000);
160	      var base = 100;
161	      var deduction = Math.min(40, this.todayAbnormal * 5);
162	      this.healthScore = Math.max(0, base - deduction);
163	      if (this.healthScore >= 80) this.scoreDesc = '体态良好，继续保持';
164	      else if (this.healthScore >= 60) this.scoreDesc = '体态一般，注意调整';
165	      else this.scoreDesc = '体态较差，请及时矫正';
166	    },
167	
168	    _startMockSensor() {
169	      var self = this;
170	      var t = 0;
171	      this._mockTimer = setInterval(function() {
172	        t += 0.02;
173	        var sample = self._genHeadDown(t);
174	        self._window.push(sample);
175	        if (self._window.length > 100) self._window.shift();
176	        if (self._window.length >= 100) {
177	          var result = self._classify(self._window);
178	          self._handleResult(result);
179	        }
180	      }, 20);
181	    },
182	
183	    _genHeadDown(t) {
184	      var progress = Math.min(t / 20, 1);
185	      var pitch = progress * 0.8;
186	      var noise = (Math.random() - 0.5) * 0.02;
187	      return {
188	        ax: 0.1 + noise,
189	        ay: 0.1 - pitch + noise,
190	        az: 0.9 - progress * 0.2 + noise,
191	        gz: noise * 2,
192	      };
193	    },
194	
195	    _classify(window) {
196	      var sumAY = 0, sumAZ = 0, sumGZ = 0;
197	      var n = window.length;
198	      for (var i = 0; i < n; i++) {
199	        sumAY += window[i].ay;
200	        sumAZ += window[i].az;
201	        sumGZ += window[i].gz;
202	      }
203	      var meanAY = sumAY / n;
204	      var meanAZ = sumAZ / n;
205	
206	      var pitch = Math.atan2(meanAY, Math.sqrt(0.01 + meanAZ * meanAZ)) * 57.3;
207	      var accMag = Math.sqrt(0.01 + meanAY * meanAY + meanAZ * meanAZ);
208	
209	      if (pitch > 30) return { type: 'HEAD_DOWN', confidence: Math.min(0.95, 0.85 + (pitch - 30) * 0.01) };
210	      if (accMag < 0.1 && pitch > 15) return { type: 'SEDENTARY', confidence: 0.82 };
211	      return { type: 'NORMAL', confidence: 0.9 };
212	    },
213	
214	    _handleResult(result) {
215	      if (result.type !== 'NORMAL') {
216	        var now = Date.now();
217	        if (this._lastType === result.type && this._anomalyStart > 0) {
218	          var dur = (now - this._anomalyStart) / 60000;
219	          var required = result.type === 'HEAD_DOWN' ? 0.17 : 0.08;
220	          if (dur >= required) {
221	            var last = this._lastReminder[result.type] || 0;
222	            if (now - last > 300000) {
223	              this._triggerReminder(result.type);
224	              this._lastReminder[result.type] = now;
225	            }
226	          }
227	        } else {
228	          this._anomalyStart = now;
229	        }
230	      } else {
231	        this._anomalyStart = 0;
232	      }
233	      this._lastType = result.type;
234	    },
235	
236	    _triggerReminder(type) {
237	      var labels = { HEAD_DOWN: '低头前倾', SEDENTARY: '久坐伏案', CROSS_LEGS: '跷二郎腿' };
238	      var label = labels[type] || '异常';
239	      this.todayAbnormal++;
240	      var d = new Date();
241	      var timeStr = (d.getHours() < 10 ? '0' : '') + d.getHours() + ':' + (d.getMinutes() < 10 ? '0' : '') + d.getMinutes();
242	      var newRecords = this.records.slice(0);
243	      newRecords.unshift({ time: timeStr, type: label });
244	      if (newRecords.length > 5) newRecords = newRecords.slice(0, 5);
245	      this.records = newRecords;
246	      try { vibrator.vibrate({ mode: 'short' }); } catch(e) {}
247	    },
248	
249	    go(url) {
250	      router.push({ uri: url });
251	    },
252	  }
